using System.Diagnostics;

public static class Coop
{
    private static int _liveRegistrations;

    /// Number of registrations Coop currently holds on caller-supplied tokens (diagnostic hook
    /// for the leak test). Must return to 0 once every returned task has completed.
    public static int LiveRegistrations => Volatile.Read(ref _liveRegistrations);

    /// Runs <paramref name="operation"/> with a token that is cancelled when the caller's token is
    /// cancelled or when <paramref name="timeout"/> elapses, whichever comes first.
    public static async Task<T> WithTimeoutAsync<T>(
        Func<CancellationToken, Task<T>> operation,
        TimeSpan timeout,
        CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(operation);
        if (timeout < TimeSpan.Zero && timeout != Timeout.InfiniteTimeSpan)
            throw new ArgumentOutOfRangeException(nameof(timeout));

        cancellationToken.ThrowIfCancellationRequested();

        // Fast path: no timer, no linked source, nothing to dispose.
        if (timeout == Timeout.InfiniteTimeSpan)
            return await operation(cancellationToken).ConfigureAwait(false);

        // The linked source registers a callback on the caller's token; disposing it removes
        // that registration, so a long-lived caller token does not accumulate garbage.
        using var linked = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
        linked.CancelAfter(timeout);
        Interlocked.Increment(ref _liveRegistrations);

        try
        {
            return await operation(linked.Token).ConfigureAwait(false);
        }
        catch (OperationCanceledException oce) when (cancellationToken.IsCancellationRequested)
        {
            // The caller asked to stop: surface it as *their* cancellation, not the linked token's.
            throw new OperationCanceledException(oce.Message, oce, cancellationToken);
        }
        catch (OperationCanceledException oce) when (linked.IsCancellationRequested)
        {
            // Only the timer fired: this is a failure, not a cancellation.
            throw new TimeoutException($"The operation did not complete within {timeout}.", oce);
        }
        finally
        {
            Interlocked.Decrement(ref _liveRegistrations); // `using` disposes `linked` right after this
        }
        // Any other exception (including an OCE thrown for a token we do not own) propagates unchanged.
    }

    /// Makes waiting on <paramref name="task"/> cancellable. The task itself keeps running.
    public static Task<T> WithCancellationAsync<T>(this Task<T> task, CancellationToken cancellationToken)
    {
        ArgumentNullException.ThrowIfNull(task);

        if (task.IsCompleted || !cancellationToken.CanBeCanceled)
            return task;

        if (cancellationToken.IsCancellationRequested)
        {
            ObserveFault(task);
            return Task.FromCanceled<T>(cancellationToken);
        }

        return Race(task, cancellationToken);

        static async Task<T> Race(Task<T> task, CancellationToken ct)
        {
            var tcs = new TaskCompletionSource<bool>(TaskCreationOptions.RunContinuationsAsynchronously);

            // Static lambda + state object: no closure allocation. The registration is removed in the
            // implicit finally of `using` whichever branch wins, so the token's callback list never grows.
            using CancellationTokenRegistration reg = ct.UnsafeRegister(
                static (state, token) => ((TaskCompletionSource<bool>)state!).TrySetCanceled(token), tcs);
            Interlocked.Increment(ref _liveRegistrations);

            try
            {
                Task completed = await Task.WhenAny(task, tcs.Task).ConfigureAwait(false);
                if (ReferenceEquals(completed, task))
                    return await task.ConfigureAwait(false); // propagates result, fault, or cancellation

                ObserveFault(task);
                throw new OperationCanceledException(ct);
            }
            finally
            {
                Interlocked.Decrement(ref _liveRegistrations);
            }
        }
    }

    // A task we walk away from must not raise TaskScheduler.UnobservedTaskException later.
    private static void ObserveFault(Task task) =>
        task.ContinueWith(static t => _ = t.Exception,
            CancellationToken.None,
            TaskContinuationOptions.OnlyOnFaulted | TaskContinuationOptions.ExecuteSynchronously,
            TaskScheduler.Default);
}

public static class Program
{
    private static int _failures;

    public static async Task Main()
    {
        // Cooperative worker: works in slices and honours the token between slices.
        static async Task<int> Work(int slices, CancellationToken ct)
        {
            int done = 0;
            for (int i = 0; i < slices; i++)
            {
                ct.ThrowIfCancellationRequested();
                await Task.Delay(20, ct);
                done++;
            }
            return done;
        }

        // Completes after a yield / a delay without ever touching .Result.
        static async Task<int> Later(int value) { await Task.Yield(); return value; }
        static async Task<int> After(int ms, int value) { await Task.Delay(ms); return value; }

        // 1. Completes before the timeout.
        Check("completes", await Coop.WithTimeoutAsync(ct => Work(3, ct), TimeSpan.FromSeconds(5)) == 3);

        // 2. Timeout only -> TimeoutException wrapping the OCE, returned task is Faulted.
        var t2 = Coop.WithTimeoutAsync(ct => Work(100, ct), TimeSpan.FromMilliseconds(100));
        await Swallow(t2);
        Check("timeout faults", t2.IsFaulted && t2.Exception!.InnerException is TimeoutException { InnerException: OperationCanceledException });

        // 3. Caller cancels -> task is Canceled and the OCE carries the caller's token.
        using var callerCts = new CancellationTokenSource(100);
        var t3 = Coop.WithTimeoutAsync(ct => Work(100, ct), TimeSpan.FromSeconds(5), callerCts.Token);
        var oce3 = await Swallow(t3) as OperationCanceledException;
        Check("caller cancel is Canceled", t3.IsCanceled && oce3 is not null && oce3.CancellationToken == callerCts.Token);

        // 4. Caller cancels *and* the timer has fired -> still the caller's cancellation.
        using var both = new CancellationTokenSource();
        var t4 = Coop.WithTimeoutAsync(async ct =>
        {
            try { await Task.Delay(-1, ct); } catch (OperationCanceledException) { }
            both.Cancel();                 // caller cancels while we are already timed out
            ct.ThrowIfCancellationRequested();
            return 0;
        }, TimeSpan.FromMilliseconds(50), both.Token);
        await Swallow(t4);
        Check("caller wins over timeout", t4.IsCanceled);

        // 5. Non-cancellation failures propagate unchanged.
        var t5 = Coop.WithTimeoutAsync<int>(_ => throw new InvalidOperationException("boom"), TimeSpan.FromSeconds(1));
        Check("other exceptions propagate", await Swallow(t5) is InvalidOperationException);

        // 6. Infinite timeout allocates no timer and passes the caller's token straight through.
        using var passThrough = new CancellationTokenSource();
        var t6 = Coop.WithTimeoutAsync(ct => Task.FromResult(ct == passThrough.Token), Timeout.InfiniteTimeSpan, passThrough.Token);
        Check("infinite timeout passes token through", await t6);

        // 7. Negative timeout other than Timeout.InfiniteTimeSpan is rejected (surfaces through the task because the method is async).
        var t7 = Coop.WithTimeoutAsync(ct => Task.FromResult(0), TimeSpan.FromSeconds(-2));
        Check("negative timeout rejected", await Swallow(t7) is ArgumentOutOfRangeException);

        // 8. WithCancellationAsync: task wins.
        using var c8 = new CancellationTokenSource(5000);
        Check("task wins", await After(10, 42).WithCancellationAsync(c8.Token) == 42);

        // 9. WithCancellationAsync: token wins; the underlying task is untouched and keeps running.
        var never = new TaskCompletionSource<int>();
        using var c9 = new CancellationTokenSource(50);
        var t9 = never.Task.WithCancellationAsync(c9.Token);
        var oce9 = await Swallow(t9) as OperationCanceledException;
        Check("token wins", t9.IsCanceled && oce9?.CancellationToken == c9.Token && !never.Task.IsCompleted);

        // 10. Already-cancelled token short-circuits without touching the task.
        using var pre = new CancellationTokenSource();
        pre.Cancel();
        var t10 = never.Task.WithCancellationAsync(pre.Token);
        Check("pre-cancelled token", t10.IsCanceled && !never.Task.IsCompleted);

        // 11. No registration leak: after 10k races the task wins, and 1k timeout-guarded calls,
        //     Coop holds no registration on the long-lived token.
        using var longLived = new CancellationTokenSource();
        for (int i = 0; i < 10_000; i++)
            await Later(i).WithCancellationAsync(longLived.Token);
        for (int i = 0; i < 1_000; i++)
            await Coop.WithTimeoutAsync(_ => Later(i), TimeSpan.FromSeconds(5), longLived.Token);
        Check("no registration leak", Coop.LiveRegistrations == 0);
        longLived.Cancel(); // must run no leftover Coop callbacks

        // 12. An abandoned task that later faults must not raise UnobservedTaskException.
        int unobserved = 0;
        TaskScheduler.UnobservedTaskException += (_, e) => { Interlocked.Increment(ref unobserved); e.SetObserved(); };
        var lateFault = new TaskCompletionSource<int>();
        using var c12 = new CancellationTokenSource(10);
        await Swallow(lateFault.Task.WithCancellationAsync(c12.Token));
        lateFault.SetException(new InvalidOperationException("late"));
        lateFault = null!;
        GC.Collect(); GC.WaitForPendingFinalizers(); GC.Collect();
        Check("abandoned fault observed", unobserved == 0);

        Console.WriteLine(_failures == 0 ? "ALL PASSED" : $"{_failures} FAILED");
    }

    private static void Check(string name, bool ok)
    {
        if (!ok) _failures++;
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")} {name}");
    }

    private static async Task<Exception?> Swallow(Task task)
    {
        try { await task; return null; }
        catch (Exception e) { return e; }
    }
}

